package model

import (
	"encoding/json"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// A server_assigned field is served as auto-generated, so a form never demands it, yet create
// validation still requires it and keeps the value the domain service stamped.
func TestFieldServerAssigned_ServedAutoGeneratedButValueKept(t *testing.T) {
	schema := ParseModelJson(`{
		"name": "test_server_assigned",
		"table_name": "test_server_assigneds",
		"fields": [
			{"name": "id", "data_type": "ulid", "primary_key": true, "use_type_default": true},
			{"name": "number", "data_type": {"type": "string", "min": 1, "max": 20},
				"required_for_create": true, "no_update": true, "metadata": {"server_assigned": true}}
		]
	}`).Build()
	field, ok := schema.Field("number")
	require.True(t, ok)
	assert.True(t, field.IsServerAssigned())
	assert.False(t, field.IsAutoGenerated(), "auto_generated would empty the stamped value on create")

	encoded, err := json.Marshal(field.ToSimplizedIn(schema.Name()))
	require.NoError(t, err)
	var decoded struct {
		IsAutoGenerated     bool `json:"is_auto_generated"`
		IsRequiredForCreate bool `json:"is_required_for_create"`
	}
	require.NoError(t, json.Unmarshal(encoded, &decoded))
	assert.True(t, decoded.IsAutoGenerated)
	assert.True(t, decoded.IsRequiredForCreate)

	sanitized, cErrs := schema.Validate(DynamicFields{"number": "TR-0001"})
	require.Equal(t, 0, cErrs.Count())
	assert.Equal(t, "TR-0001", sanitized["number"])

	_, cErrs = schema.Validate(DynamicFields{})
	assert.Equal(t, 1, cErrs.Count(), "an unstamped create is still refused")
}

func TestFieldServerAssigned_AbsentOrNotBool(t *testing.T) {
	plain := DefineField().Name("plain").DataType(FieldDataTypeString(0, 10)).Build()
	assert.False(t, plain.IsServerAssigned())
	wrongType := DefineField().Name("wrong").DataType(FieldDataTypeString(0, 10)).
		Metadata(map[string]any{MetadataServerAssigned: "yes"}).Build()
	assert.False(t, wrongType.IsServerAssigned())
}
